{ arg out=0, freq=440, amp=0.1, gate=1, rq=0.5, cutoff=2000;
    var sig;
    var env = EnvGen.ar(
        Env.adsr(0.01, 0.3, 0.7, 0.5, curve: -4),
        gate: gate,
        doneAction: 2
    );
    // Saw oscillator
    sig = Saw.ar(freq);
    // Low-pass filter with resonance
    sig = RLPF.ar(sig, cutoff, rq);
    sig = sig * amp * env;
    Out.ar(out, sig ! 2);
}
